{ id: "ARC-M11", subject: "Maths", topicKey: "areas-related-to-circles", subtopic: "Composite Figures", section: "B", marks: 2, format: "Short", difficulty: "Medium", bloomSkill: "Applying", questionText: "Find the area of the shaded region where an equilateral triangle of side 6 cm has a circle of radius 1 cm at each vertex (each sector inside the triangle).", solutionSteps: [
      "Area of triangle = (√3/4) × 36 = 9√3 ≈ 15.59 cm² [½]",
      "Each vertex angle = 60°, 3 sectors = 3 × (60/360) × π(1)² = π/2 ≈ 1.57 cm² [½]",
      "Shaded = 15.59 − 1.57 ≈ 14.02 cm² [1]",
    ], finalAnswer: "≈ 14.02 cm²" , isCompetencyBased: true }

{ id: "HE-H04", subject: "Science", topicKey: "heredity", subtopic: "Mendel's Laws", section: "E", marks: 4, format: "Case-Based", difficulty: "Hard", bloomSkill: "Evaluating", questionText: "A couple has four children — two boys and two girls. The father is colour-blind (X^c Y) and the mother is a carrier (X^C X^c).\n(i) What percentage of their sons will be colour-blind?\n(ii) What percentage of their daughters will be carriers?\n(iii) Can any daughter be colour-blind? Show with a cross.\n(iv) Why is colour-blindness more common in males?", solutionSteps: [
      "Punnett Square: Set up a 2×2 grid. Write the two parental gametes along the top and left side. Fill all four cells to obtain offspring genotypes. State the genotypic ratio and phenotypic ratio.; Cross: X^C X^c × X^c Y [1]",
      "Sons: X^C Y (normal) and X^c Y (colour-blind) — 50% colour-blind sons; Daughters: X^C X^c (carrier) and X^c X^c (colour-blind) — 50% carriers, 50% colour-blind [1]",
      "(iii) Yes, X^c X^c daughter is colour-blind [1]",
      "(iv) Males have only one X; one defective X = colour-blind. Females need both X defective [1]",
    ], finalAnswer: "(i) 50% (ii) 50% (iii) Yes (iv) Males have single X; one defective = affected" , visualExplainerId: "science-heredity-evolution-mendels-laws-of-inheritance", isCompetencyBased: true }

{ id: "PLE-M10", subject: "Maths", topicKey: "pair-of-linear-equations", subtopic: "Word & Application Problems", section: "E", marks: 4, format: "Case-Based", difficulty: "Medium", bloomSkill: "Analysing", questionText: "In a class test, the sum of Shefali's marks in Mathematics and English is 30. Had she got 2 more marks in Mathematics and 3 marks less in English, the product of their marks would have been 210.\n(i) Form the pair of linear equations.\n(ii) Solve the equations.\n(iii) Find her marks in each subject.\n(iv) Is the pair of equations consistent?", solutionSteps: [
      "Let Maths = x, English = y; (i) x + y = 30 and (x+2)(y−3) = 210 [1]",
      "(ii) From x + y = 30: y = 30 − x; (x+2)(27−x) = 210 → 27x − x² + 54 − 2x = 210 → x² − 25x + 156 = 0 [1]",
      "(x−12)(x−13) = 0 → x = 12 or 13; (iii) If x=12, y=18 or x=13, y=17 [1]",
      "(iv) Yes, consistent (has solutions) [1]",
    ], finalAnswer: "(12, 18) or (13, 17)" , visualExplainerId: "maths-linear-equations-consistency-of-equations", isCompetencyBased: true }

{ id: "STAT-H10", subject: "Maths", topicKey: "statistics", subtopic: "Mean (Step Deviation)", section: "C", marks: 3, format: "Short", difficulty: "Hard", bloomSkill: "Analysing", questionText: "In a frequency distribution, if the mean is 15, mode is 18, find the median and comment on the skewness.", solutionSteps: [
      "Mode = 3 Median − 2 Mean [1]",
      "18 = 3M − 30 → M = 16 [1]",
      "Since Mean < Median < Mode, the distribution is negatively skewed [1]",
    ], finalAnswer: "Median = 16; negatively skewed" , visualExplainerId: "maths-statistics-median-of-grouped-data", isCompetencyBased: true }

{ id: "SAV-M10", subject: "Maths", topicKey: "surface-areas-and-volumes", subtopic: "Combination/Transformation", section: "C", marks: 3, format: "Short", difficulty: "Medium", bloomSkill: "Applying", questionText: "A solid consisting of a right circular cone of height 120 cm and radius 60 cm standing on a hemisphere of radius 60 cm is placed upright in a right circular cylinder full of water such that it touches the bottom. Find the volume of water left in the cylinder if the radius of the cylinder is 60 cm and height is 180 cm.", solutionSteps: [
      "V_cyl = π(3600)(180) = 648000π; V_cone = (1/3)π(3600)(120) = 144000π [1]",
      "V_hemi = (2/3)π(216000) = 144000π; V_solid = 144000π + 144000π = 288000π [1]",
      "Water left = 648000π − 288000π = 360000π ≈ 1131428.57 cm³ [1]",
    ], finalAnswer: "360000π cm³" , visualExplainerId: "maths-surface-areas-volumes-surface-area-formulas", isCompetencyBased: true }

{ id: "SAV2P1-R02", subject: "Maths", topicKey: "surface-areas-and-volumes", subtopic: "Combination/Transformation", section: "C", marks: 3, format: "Short", difficulty: "Medium", bloomSkill: "Applying", questionText: "A hemispherical bowl of internal radius 9 cm contains a liquid. The liquid is to be filled into cylindrical bottles each of radius 1.5 cm and height 4 cm. How many bottles are needed?", solutionSteps: [
      "V_bowl = (2/3)π(729) = 486π cm³ [1]",
      "V_bottle = π(2.25)(4) = 9π cm³ [1]",
      "Number = 486/9 = 54 [1]",
    ], finalAnswer: "54 bottles", visualExplainerId: "maths-surface-areas-volumes-surface-area-formulas", isCompetencyBased: true }
